import shutil
import sys
import tempfile
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
sys.path.insert(0, ROOT)


def attempt(fn, *args, **kw):
    """Call fn; return its result, or None when it refused (raised)."""
    try:
        return fn(*args, **kw)
    except Exception:  # noqa: BLE001
